//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::array::byte_array_get`; the
//! native twin is `benches/native/Bench/ArrayByteArrayGet.lean`.
//! half the indices are out of bounds (0, no message)

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::array;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &Vec<u8>, n: u64) -> u64 {
    let b = &inp[..];
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            array::byte_array_get(b, nat_unbox(nat_box(x >> 51))) as u64,
        );
    }
    acc
}

fn main() {
    run(|| byte_operands(), kernel)
}
